/* The C library surface the static program exports to a shared object it loads (src/linux/libc/loader.cpp).
   A plugin's undefined symbols are resolved against this list. CMake reads this file twice: every name
   becomes an entry in the program's export table (loader_exports.inc), which is what the loader
   resolves imports through, and the allocator's names (the only libc definitions with default
   visibility, so the only ones a static link can put in the dynamic symbol table) also become the
   linker's dynamic list and version script. The rest of src/linux/libc hides its definitions (CL in
   those files), and hidden visibility is final: a version script cannot promote one into .dynsym, so
   the table is what carries them. Generated from the global, non-TLS symbols the libc objects define;
   thread-local variables are left out on purpose, since a table of addresses could not name them, and
   so are the loader's own entry points (dlopen and its neighbours), which are not things an object
   asks the program for. Generated from the global, non-TLS symbols the libc objects define:
   `readelf -sW <libc objects> | awk '$5 == "GLOBAL" && $7 != "UND" && $4 != "TLS" {print $8}'`,
   sorted, minus the loader's own names; regenerate it the same way when the surface grows (see
   docs/linux-libc.md, "Static-PIE and the loader"). Only the static build links this file. The
   dynamic build exports nothing. */
CORDINAL_1 {
  global:
    __ctype_get_mb_cur_max;
    __cxa_atexit;
    __cxa_finalize;
    __cxa_thread_atexit_impl;
    __duplocale;
